using Ror2Common;
using RoR2;

namespace Samus
{
    // Melee characters' entries in the pause menu's controls window. Every sheet is
    // generated by ror2-common's MeleeSheet from the fighter's own skill layout
    // (the same names the loadout and HUD show) plus the generic Melee control
    // scheme, worded by the fighter's own move list (so only a fighter with a rapid
    // jab says so); a fighter adds only a subtitle and any inputs unique to it.
    // Pad names match the buttons the native sim reads (MeleePad), not RoR2's
    // rebindable skill slots. One page, rows of a few words, like Olimar's.
    internal static class MeleeSheets
    {
        public static ControlSheet SamusSheet(CharacterBody body) => MeleeSheet.Build(
            "Intergalactic Bounty Hunter", Skills.Layout, body: body,
            footer: "X is also RoR2's interact: with a prompt up it goes to that, not the grapple.",
            grab: (pad, keys) =>
            {
                pad.Add("X", "Grapple beam (bosses pull you in)")
                    .Add("Captured", "LT pummel, LS + LT throw")
                    .Add("X + LT, or A", "Let go");
                keys.Add("Interact", "Grapple beam (bosses pull you in)")
                    .Add("Captured", "Secondary pummel, Move throw")
                    .Add("Jump", "Let go");
            });

        public static ControlSheet FoxSheet(CharacterBody body) => MeleeSheet.Build("Leader of Star Fox", Fox.FoxSkills.Layout, body: body);
        public static ControlSheet LuigiSheet(CharacterBody body) => MeleeSheet.Build("The Eternal Understudy", Luigi.LuigiSkills.Layout, body: body);
        public static ControlSheet CaptainSheet(CharacterBody body) => MeleeSheet.Build("F-Zero Racer", Captain.CaptainSkills.Layout, body: body);
        public static ControlSheet LinkSheet(CharacterBody body) => MeleeSheet.Build("Hero of Hyrule", Link.LinkSkills.Layout, body: body);
        public static ControlSheet PikachuSheet(CharacterBody body) => MeleeSheet.Build(
            "The Electric Mouse Pokemon", Pikachu.PikachuSkills.Layout, body: body,
            footer: "Quick Attack homes on your lock-on, in two zips: turn the stick or press LB again for the second.");
        public static ControlSheet YoshiSheet(CharacterBody body) => MeleeSheet.Build("Yoshi's Island Dinosaur", Yoshi.YoshiSkills.Layout, body: body);
        public static ControlSheet DonkeySheet(CharacterBody body) => MeleeSheet.Build("King of the Jungle", Donkey.DonkeySkills.Layout, body: body);
    }
}
